UPDATE `competence` c JOIN `matiere` mt ON mt.`id` = c.`id_matiere` SET c.`libelle` = 'Produce sentences using moods correctly in the target national language dealing with media and communication' WHERE mt.`libelle` = 'NATIONAL LANGUAGES' AND c.`libelle` COLLATE utf8mb4_bin = 'Produce sentences using moods correctly  in the target national language dealing with media and communication';

-- Doublons devenus identiques : on garde le plus ancien, seulement s'ils n'ont aucune note
DELETE c FROM `competence` c
JOIN `competence` k ON k.`id_matiere` = c.`id_matiere` AND k.`code_niveau` = c.`code_niveau`
                    AND k.`id_trim` = c.`id_trim` AND k.`libelle` = c.`libelle` AND k.`id` < c.`id`
WHERE NOT EXISTS (SELECT 1 FROM `note` n WHERE n.`id_competence` = c.`id`)
  AND NOT EXISTS (SELECT 1 FROM `absence_justifiee` a WHERE a.`id_competence` = c.`id`);
